tasks.solution:
fn main() {
    let prices = vec![1200, 1800, 900];
    // 반복마다 가격을 더해 갈 합계예요.
    let mut total = 0;
    // 이 줄을 고쳐 prices를 빌려서 반복하세요.
    // &prices로 빌리면 price는 원소를 가리키는 참조예요. 목록은 prices가 계속 소유해요.
    for price in &prices {
        total += price;
    }
    println!("합계: {total}");
    // 반복 뒤에도 빌려준 목록을 그대로 쓸 수 있어요.
    println!("상품 수: {}", prices.len());
}

