tasks.solution:
fn main() {
    let prices = vec![1200, 1800];
    let index: usize = 1;
    // 두 갈래의 출력을 고쳐 Some이면 가격을, None이면 상품 없음을 출력하세요.
    // get의 결과 모양에 따라 두 갈래 중 하나만 실행돼요.
    match prices.get(index) {
        // 값이 있으면 Some 안의 값을 price라는 이름으로 꺼내요.
        Some(price) => println!("가격: {price}"),
        // 값이 없을 때의 갈래예요. 이 갈래를 빼면 match가 컴파일되지 않아요.
        None => println!("상품 없음"),
    }
}

