    }
}

tasks.solution:
// 검사를 통과하면 Ok(수량), 실패하면 Err(이유)를 돌려줘요.
fn check_qty(qty: i32) -> Result<i32, String> {
    // 주문 수량은 1개 이상이어야 해요.
    if qty > 0 { Ok(qty) } else { Err(String::from("수량은 1개 이상이어야 해요")) }
}

fn main() {
    let qty = 3;
    // 두 갈래의 출력을 고쳐 Ok면 수량을, Err면 거절 이유를 출력하세요.
    match check_qty(qty) {
        // 성공이면 Ok 안의 수량을 n으로 꺼내요.
        Ok(n) => println!("주문 수량: {n}"),
        // 실패면 Err 안의 이유 String을 message로 꺼내 그대로 보여 줘요.
        Err(message) => println!("주문 거절: {message}"),
    }
}

