tasks.solution:
fn main() {
    // 주문서에 적힌 수량 문구예요.
    let text = "12";
    // 이 줄을 고쳐 text.parse::<i32>()의 결과로 나누세요.
    // text는 글자라 바로 Ok·Err로 나눌 수 없어요. parse가 돌려준 Result를 나눠요.
    match text.parse::<i32>() {
        // 바꾸기에 성공하면 Ok 안의 정수를 qty로 꺼내요.
        Ok(qty) => println!("수량: {qty}"),
        // 숫자가 아닌 글자가 섞이면 이 갈래예요. 안의 오류 값은 쓰지 않아요.
        Err(_) => println!("숫자가 아니에요"),
    }
}

