tasks.solution:
fn main() {
    let text = "abc";
    // 바꾸기에 성공했는지 실패했는지를 갈래로 나눠요.
    match text.parse::<i32>() {
        // 정말 0을 적었으면 이 갈래에서 수량: 0이 나와요.
        Ok(qty) => println!("수량: {qty}"),
        // 이 줄을 고쳐 변환 실패를 수량 0이 아니라 실패로 알리세요.
        // 실패를 0으로 바꿔 말하면 진짜 0과 구별되지 않아요.
        Err(_) => println!("수량을 읽지 못했어요"),
    }
}

