fn main() {
    // 가격 조회는 값이 있거나 없는 Option으로 끝나요.
    let prices = vec![1200, 1800];
    let index: usize = 5;
    match prices.get(index) {
        Some(price) => println!("가격: {price}"),
        // 이 줄을 고쳐 찾는 상품이 없다고 알리세요.
        // None은 조회한 위치에 상품이 없다는 뜻이에요.
        None => println!("상품 없음"),
    }

    // 수량 변환은 성공하거나 실패하는 Result로 끝나요.
    let text = "두 개";
    match text.parse::<i32>() {
        Ok(qty) => println!("수량: {qty}"),
        // 이 줄을 고쳐 수량을 읽지 못했다고 알리세요.
        // Err는 적힌 글자를 정수로 읽지 못했다는 뜻이에요. 상품이 없는 것과 달라요.
        Err(_) => println!("수량을 읽지 못했어요"),
    }
}
